import axios from 'axios';

// URL de base de l'API
const API_URL = 'http://localhost:5000/api'; // Ajustez selon votre configuration

// Fonction pour se connecter
export const login = async (email, password) => {
  // Simulation temporaire de connexion
  if (email === 'tamby105@gmail.com' && password === 'qwerty123') {
    // Créer un faux token et utilisateur pour la simulation
    const mockResponse = {
      token: 'fake-jwt-token-for-simulation-purposes',
      user: {
        id: 1,
        email: 'tamby105@gmail.com',
        name: 'Tamby',
        role: 'admin'
      }
    };
    
    // Stocker dans localStorage comme si c'était une vraie réponse d'API
    localStorage.setItem('authToken', mockResponse.token);
    localStorage.setItem('user', JSON.stringify(mockResponse.user));
    
    return mockResponse;
  }
  
  // Si les identifiants ne correspondent pas à la simulation, essayer l'API réelle
  try {
    const response = await axios.post(`${API_URL}/auth/login`, { email, password });
    
    // Stocker le token dans le localStorage
    if (response.data.token) {
      localStorage.setItem('authToken', response.data.token);
      localStorage.setItem('user', JSON.stringify(response.data.user));
      return response.data;
    }
    
    throw new Error('Authentification échouée');
  } catch (error) {
    console.error('Erreur lors de la connexion:', error);
    throw error;
  }
};

// Fonction pour se déconnecter
export const logout = () => {
  localStorage.removeItem('authToken');
  localStorage.removeItem('user');
};

// Vérifier si l'utilisateur est connecté
export const isAuthenticated = () => {
  const token = localStorage.getItem('authToken');
  return !!token;
};

// Récupérer l'utilisateur connecté
export const getCurrentUser = () => {
  const user = localStorage.getItem('user');
  return user ? JSON.parse(user) : null;
};

// Récupérer le token d'authentification
export const getAuthToken = () => {
  return localStorage.getItem('authToken');
};

// Configurer les en-têtes d'autorisation pour les requêtes axios
export const setAuthHeader = () => {
  const token = getAuthToken();
  if (token) {
    axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  } else {
    delete axios.defaults.headers.common['Authorization'];
  }
};
